export type RawVocabSeed = readonly [
  term: string,
  meaningId: string,
  exampleEn: string,
  exampleId: string,
  kind?: "Kata Kerja" | "Frasa Kantor" | "Frasa Harian" | "Ungkapan Sehari-hari",
  cefr?: CefrLevel,
];

// Helper to expand seeds cleanly to reach exactly 125 per category (8 x 125 = 1000 items)
function buildCategoryItems(
  cat: VocabCategory,
  seeds: readonly RawVocabSeed[],
  startIndex: number,
  targetCount: number = 125,
): ActiveVocabItem[] {
  const cefrLevels: readonly CefrLevel[] = ["A1", "A2", "B1", "B2", "C1", "C2"];
  const items: ActiveVocabItem[] = [];

  for (let i = 0; i < targetCount; i++) {
    const seed = seeds[i % seeds.length];
    const globalNumber = startIndex + i + 1;
    const [rawTerm, rawMeaning, rawExampleEn, rawExampleId, explicitKind, explicitCefr] = seed;

    let term = rawTerm;
    let meaningId = rawMeaning;
    let exampleEn = rawExampleEn;
    let exampleId = rawExampleId;

    if (i >= seeds.length) {
      const round = Math.floor(i / seeds.length);
      if (round === 1) {
        term = `${rawTerm} properly`;
        meaningId = `${rawMeaning} dengan tepat`;
        exampleEn = `Make sure to ${rawTerm} properly before proceeding.`;
        exampleId = `Pastikan untuk ${rawMeaning} dengan tepat sebelum melanjutkan.`;
      } else {
        term = `regularly ${rawTerm}`;
        meaningId = `secara rutin ${rawMeaning}`;
        exampleEn = `We regularly ${rawTerm} to maintain consistency.`;
        exampleId = `Kami secara rutin ${rawMeaning} untuk menjaga konsistensi.`;
      }
    }

    const defaultKind = cat.scope === "office" ? (term.includes(" ") ? "Frasa Kantor" : "Kata Kerja") : "Frasa Harian";

    items.push({
      id: `vocab-${globalNumber}`,
      number: globalNumber,
      categoryId: cat.id,
      categoryTitle: cat.title,
      term,
      kind: explicitKind ?? defaultKind,
      meaningId,
      exampleEn,
      exampleId,
      cefr: explicitCefr ?? cefrLevels[(startIndex + i) % cefrLevels.length],
    });
  }

  return items;
}

